// Selecciona el estado objetivo de la semana y configura criterios de búsqueda
const estadosNorte = [
  'Baja California',
  'Baja California Sur',
  'Sonora',
  'Chihuahua',
  'Coahuila',
  'Durango',
  'Nuevo León',
  'Tamaulipas'
];

const girosObjetivo = [
  'Manufactura y Maquiladoras',
  'Transporte Terrestre y Flotillas de Carga',
  'Minería y Metalurgia',
  'Sindicatos Industriales y de la Transformación',
  'Universidades e Institutos Tecnológicos',
  'Agroindustria y Distribución'
];

// Rotación por semana del año
const weekNumber = Math.floor((Date.now() - new Date(new Date().getFullYear(), 0, 1)) / (7 * 24 * 60 * 60 * 1000));
const estadoSeleccionado = estadosNorte[weekNumber % estadosNorte.length];
const giroSeleccionado = girosObjetivo[weekNumber % girosObjetivo.length];

return [
  {
    json: {
      estado: estadoSeleccionado,
      giro: giroSeleccionado,
      cantidad: 5,
      timestamp: new Date().toISOString(),
      reglas: {
        minimoEmpleados: 50,
        minimoFlotilla: 20,
        excluir: ['maestros', 'snte', 'cnte', 'telefonistas', 'strm']
      }
    }
  }
];

// Auditoría y Validación de Calificación de Suscripción Quálitas
const response = $input.first().json;

if (!response.success || !response.data) {
  throw new Error('La consulta de IA no devolvió datos exitosos');
}

const items = response.data;
const validados = [];

for (const p of items) {
  const textoCompleto = `${p.razonSocial} ${p.giro} ${p.responsables?.[0]?.cargo || ''}`.toLowerCase();

  // 1. REGLA OBLIGATORIA: Excluir sindicatos de maestros y telefonistas
  if (
    textoCompleto.includes('maestro') ||
    textoCompleto.includes('snte') ||
    textoCompleto.includes('cnte') ||
    textoCompleto.includes('telefonista') ||
    textoCompleto.includes('strm')
  ) {
    continue;
  }

  // 2. REGLA OBLIGATORIA: >50 empleados O >20 vehículos
  const numEmp = parseInt(p.numeroEmpleados || 0, 10);
  const numVeh = parseInt(p.numeroVehiculos || 0, 10);

  if (numEmp >= 50 || numVeh >= 20 || textoCompleto.includes('sindicato') || textoCompleto.includes('universidad')) {
    validados.push({
      ...p,
      fuente: 'Flujo n8n Semanal Automatizado',
      fechaValidacion: new Date().toISOString()
    });
  }
}

return [
  {
    json: {
      validados,
      totalAprobados: validados.length,
      proveedorUsado: response.providerUsed,
      modeloUsado: response.modelUsed,
      latenciaMs: response.latencyMs
    }
  }
];
